<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { Ban, Plus, RefreshCw } from 'lucide-vue-next'
import { api, apiError } from '../api/client';import type { ApiResponse, Payment, Paginated, Receivable } from '../types'
import PageHeader from '../components/PageHeader.vue';import DrawerPanel from '../components/DrawerPanel.vue';import InlineAlert from '../components/InlineAlert.vue';import StatusBadge from '../components/StatusBadge.vue';import EmptyState from '../components/EmptyState.vue'
const items=ref<Payment[]>([]),receivables=ref<Receivable[]>([]),drawer=ref(false),error=ref(''),success=ref('')
const form=reactive({receivable_id:'',external_id:'',amount:'0',paid_at:new Date().toISOString().slice(0,16),payment_method:'TRANSFER',provider:'MANUAL'})
const money=(v:string)=>Number(v).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})
async function load(){try{const [p,r]=await Promise.all([api.get<ApiResponse<Payment[]>>('/v1/payments'),api.get<Paginated<Receivable>>('/v1/receivables',{params:{per_page:200}})]);items.value=p.data.data;receivables.value=r.data.data}catch(e){error.value=apiError(e)}}
function open(){const r=receivables.value.find(x=>!['PAID','CANCELLED','REVERSED'].includes(x.status));Object.assign(form,{receivable_id:r?.id||'',external_id:`MANUAL-${Date.now()}`,amount:r?.balance||'0',paid_at:new Date().toISOString().slice(0,16),payment_method:'TRANSFER',provider:'MANUAL'});drawer.value=true}
async function save(){try{await api.post('/v1/payments',{...form,amount:Number(form.amount),paid_at:new Date(form.paid_at).toISOString()});drawer.value=false;success.value='Pagamento registrado.';await load()}catch(e){error.value=apiError(e)}}
async function reverse(item:Payment){const reason=prompt('Motivo do estorno:');if(!reason)return;try{await api.post(`/v1/payments/${item.id}/reverse`,{reason});success.value='Pagamento estornado.';await load()}catch(e){error.value=apiError(e)}}
onMounted(load)
</script>
<template><PageHeader title="Pagamentos" subtitle="Liquidações recebidas por API, PIX, CNAB, conciliação ou lançamento manual."><button class="btn-secondary" @click="load"><RefreshCw :size="18"/>Atualizar</button><button class="btn-primary" @click="open"><Plus :size="18"/>Registrar pagamento</button></PageHeader><InlineAlert :message="error" @dismiss="error=''"/><InlineAlert :message="success" type="success" @dismiss="success=''"/><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Recebível</th><th>Origem</th><th>Identificador</th><th>Valor</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="item in items" :key="item.id" class="border-t border-slate-100"><td>{{new Date(item.paid_at).toLocaleString('pt-BR')}}</td><td><RouterLink :to="`/receivables?id=${item.receivable_id}`" class="font-mono text-xs text-teal-700">{{item.receivable_id.slice(0,8)}}…</RouterLink></td><td>{{item.payment_method}}<p class="text-xs text-slate-400">{{item.provider}}</p></td><td><p class="max-w-xs truncate font-mono text-xs">{{item.external_id}}</p><p v-if="item.end_to_end_id" class="max-w-xs truncate text-xs text-slate-400">E2E {{item.end_to_end_id}}</p></td><td class="font-bold">{{money(item.amount)}}</td><td><StatusBadge :status="item.status"/></td><td class="text-right"><button v-if="item.status==='CONFIRMED'" class="btn-secondary px-3 py-2 text-rose-600" @click="reverse(item)"><Ban :size="16"/>Estornar</button></td></tr></tbody></table><EmptyState v-if="!items.length" title="Nenhum pagamento registrado"/></div><DrawerPanel :open="drawer" title="Registrar pagamento manual" width="lg" @close="drawer=false"><form class="grid gap-4 md:grid-cols-2" @submit.prevent="save"><div class="md:col-span-2"><label class="label">Recebível</label><select v-model="form.receivable_id" class="select" required><option v-for="r in receivables.filter(x=>!['PAID','CANCELLED','REVERSED'].includes(x.status))" :key="r.id" :value="r.id">{{r.document_number}} · {{money(r.balance)}} · vence {{new Date(r.due_date+'T00:00:00').toLocaleDateString('pt-BR')}}</option></select></div><div><label class="label">Valor</label><input v-model="form.amount" type="number" step="0.01" min="0.01" class="input" required/></div><div><label class="label">Pago em</label><input v-model="form.paid_at" type="datetime-local" class="input" required/></div><div><label class="label">Método</label><select v-model="form.payment_method" class="select"><option>TRANSFER</option><option>PIX</option><option>CASH</option><option>CARD</option><option>CNAB</option><option>OTHER</option></select></div><div><label class="label">Provider</label><input v-model="form.provider" class="input uppercase"/></div><div class="md:col-span-2"><label class="label">Identificador externo</label><input v-model="form.external_id" class="input" required/></div><div class="md:col-span-2 flex justify-end gap-2 border-t pt-4"><button type="button" class="btn-secondary" @click="drawer=false">Cancelar</button><button class="btn-primary">Registrar</button></div></form></DrawerPanel></template>
